/* ===================== BÀI 7 · Tìm nạp, giải mã và thực thi ===================== */
/* Bài 7 · Tìm nạp, giải mã và thực thi (AMTS-EMB-001-M02-L03, MC51-007) — sinh bởi tools/author/mcu8051/l07.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR7=[{"label":"Ví dụ: Một lệnh từ ROM vào thanh ghi","code":"; Ví dụ 1: một lệnh đi từ bộ nhớ chương trình vào A\n        ORG     0000H\n        MOV     A,#5AH                  ; 74 5A: nạp 74, giải mã, nạp 5A\n        MOV     R3,A                    ; FB: số thanh ghi nằm trong mã\n        SJMP    $\n        END\n","note":"Bấm Từng bước: PC từ 0000H nhảy lên 0002H vì CPU đã nạp hai byte 74H và 5AH. Lệnh thứ hai FBH = 1111 1011B: 11111 là MOV Rn,A, 011 là R3.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: MOV direct,direct: nguồn trước đích","code":"; Ví dụ 2: MOV direct,direct ghi địa chỉ NGUỒN trước\n        ORG     0000H\n        MOV     30H,#0C3H               ; 75 30 C3\n        MOV     31H,30H                 ; 85 30 31\n        MOV     P1,31H                  ; 85 31 90\n        SJMP    $\n        END\n","note":"Viết MOV 31H,30H nhưng mã máy là 85 30 31: nguồn 30H đứng trước đích 31H. Lệnh thứ ba chép 31H ra P1 (85 31 90), 4 LED P1.2–P1.5 sáng vì C3H = 1100 0011B.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Giải mã SJMP, AJMP và LJMP","code":"; Ví dụ 3: giải mã ba kiểu lệnh nhảy\n        ORG     0000H\n        SJMP    B2                      ; 0000H: 80 + độ dời\n        NOP                             ; 0002H: bị nhảy qua\nB2:     AJMP    B3                      ; 0003H: 3 bit cao nằm trong mã\n        NOP\n        NOP\nB3:     LJMP    B4                      ; 0007H: 02 + địa chỉ 16 bit\n        NOP\nB4:     MOV     A,#77H                  ; 000BH\n        SJMP    $\n        END\n","note":"SJMP: 80 01 (0002H + 1 = 0003H). AJMP: 01 07, bit 10–8 của đích nằm ở 3 bit cao của mã lệnh (000) và byte sau là 07H. LJMP: 02 00 0B, đủ 16 bit. Ba NOP (00H) không bao giờ chạy.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Chương trình chỉ viết bằng DB","code":"; Ví dụ 4: CPU chỉ thấy byte. Chương trình dưới viết\n; toàn bằng DB, không có tên lệnh nào. Đoán từng lệnh.\n        ORG     0000H\n        DB      74H,05H                 ; lệnh 1\n        DB      24H,03H                 ; lệnh 2\n        DB      0F5H,30H                ; lệnh 3\n        DB      80H,0FEH                ; lệnh 4\n        END\n","note":"Không có tên lệnh nào trong mã nguồn. Đoán từng lệnh trước khi bấm Từng bước, rồi so với dòng mô tả trong phần Thanh ghi: MOV A,#05H, ADD A,#03H, MOV 30H,A, SJMP $.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: CPU chạy vào bảng dữ liệu","code":"; Bẫy: bảng DB nằm ngay trên đường chạy của CPU\n        ORG     0000H\n        MOV     A,#10H\nBANG:   DB      04H,04H,0F5H,30H        ; dữ liệu hay lệnh?\n        SJMP    $\n        END\n","note":"Sau MOV A,#10H, PC trỏ vào bảng. Các byte 04H, 04H, F5H 30H được chạy như INC A, INC A, MOV 30H,A. Đoán trước: ô 30H cuối bằng bao nhiêu? (12H.)","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Nhảy vào giữa một lệnh","code":"; Bẫy: nhảy vào giữa một lệnh\n        ORG     0000H\n        SJMP    GIUA+1                  ; tới byte thứ hai của lệnh dưới\nGIUA:   MOV     A,#04H                  ; 74 04\n        MOV     30H,A\n        SJMP    $\n        END\n","note":"SJMP GIUA+1 đưa PC vào 0003H, byte thứ hai của MOV A,#04H. CPU giải mã 04H thành INC A: A = 01H thay vì 04H, rồi chạy tiếp MOV 30H,A.","dev":{"led":true},"fosc":12000000}];
const sim7=makeSim51(document.getElementById("m51-l7"),{id:"s7",presets:PR7,ram:256});
makeEx51(document.getElementById("ex-l7"),"l7",[{"t":"Tự mã hóa MOV direct,#data","d":"<p>Ô <code>40H<\/code> chứa một địa chỉ trực tiếp <i>d<\/i>, ô <code>41H<\/code> chứa một số <i>n<\/i>. Ghi vào <code>30H<\/code>, <code>31H<\/code>, <code>32H<\/code> đúng ba byte mã máy của lệnh <code>MOV d,#n<\/code> theo thứ tự trong bộ nhớ chương trình; ghi số byte của lệnh vào <code>33H<\/code> và số chu kỳ máy vào <code>34H<\/code>. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>40H = 90H<\/code>, <code>41H = FEH<\/code> (lệnh <code>MOV P1,#0FEH<\/code>) → <code>30H..34H = 75H 90H FEH 03H 02H<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     30H,#75H                ; mã lệnh MOV direct,#data\n        MOV     31H,41H                 ; byte thứ hai?\n        MOV     32H,40H                 ; byte thứ ba?\n; Viết thêm: số byte vào 33H, số chu kỳ vào 34H\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x40":144,"0x41":254,"0x30":238,"0x31":238,"0x32":238,"0x33":238,"0x34":238}},"expect":{"iram":{"0x30":117,"0x31":144,"0x32":254,"0x33":3,"0x34":2}}},{"setup":{"iram":{"0x40":48,"0x41":0,"0x30":238,"0x31":238,"0x32":238,"0x33":238,"0x34":238}},"expect":{"iram":{"0x30":117,"0x31":48,"0x32":0,"0x33":3,"0x34":2}}},{"setup":{"iram":{"0x40":224,"0x41":85,"0x30":238,"0x31":238,"0x32":238,"0x33":238,"0x34":238}},"expect":{"iram":{"0x30":117,"0x31":224,"0x32":85,"0x33":3,"0x34":2}}},{"setup":{"iram":{"0x40":0,"0x41":255,"0x30":238,"0x31":238,"0x32":238,"0x33":238,"0x34":238}},"expect":{"iram":{"0x30":117,"0x31":0,"0x32":255,"0x33":3,"0x34":2}}},{"setup":{"iram":{"0x40":255,"0x41":1,"0x30":238,"0x31":238,"0x32":238,"0x33":238,"0x34":238}},"expect":{"iram":{"0x30":117,"0x31":255,"0x32":1,"0x33":3,"0x34":2}}},{"setup":{"iram":{"0x40":130,"0x41":52,"0x30":238,"0x31":238,"0x32":238,"0x33":238,"0x34":238}},"expect":{"iram":{"0x30":117,"0x31":130,"0x32":52,"0x33":3,"0x34":2}}}]},"hints":["Mã lệnh của MOV direct,#data luôn là 75H; byte nào đứng ngay sau mã lệnh?","Thứ tự là: mã lệnh, địa chỉ, dữ liệu. Code mẫu đảo hai byte cuối.","Mã lệnh là hằng; hai byte toán hạng lấy từ ô nào và ghi vào ô nào? Độ dài và số chu kỳ cũng là hằng, tra trong bảng tập lệnh."],"why":"Khi giải mã, CPU đọc byte thứ hai của 75H như địa chỉ và byte thứ ba như dữ liệu. Đảo hai byte làm lệnh ghi vào một ô khác: MOV P1,#0FEH thành MOV 0FEH,#90H. Lệnh dài 3 byte nhưng chỉ 2 chu kỳ máy: số byte và số chu kỳ là hai con số khác nhau."},{"t":"Giải mã MOV A,Rn","d":"<p>Ô <code>30H<\/code> chứa mã lệnh của một lệnh <code>MOV A,Rn<\/code> (E8H–EFH), ô <code>31H<\/code> chứa số băng thanh ghi đang dùng (0–3). Ghi vào <code>32H<\/code> địa chỉ RAM của thanh ghi Rn mà lệnh đọc, và vào <code>33H<\/code> mã lệnh của <code>MOV Rn,A<\/code> với cùng n. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = EAH<\/code> (MOV A,R2), <code>31H = 01H<\/code> → <code>32H = 0AH<\/code>, <code>33H = FAH<\/code> (MOV R2,A).<\/p>","start":"        ORG     0000H\n        MOV     A,30H                   ; mã lệnh E8H..EFH\n; Viết code: 32H = địa chỉ Rn, 33H = mã MOV Rn,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":234,"0x31":1,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":234,"0x31":1,"0x32":10,"0x33":250}}},{"setup":{"iram":{"0x30":232,"0x31":0,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":232,"0x31":0,"0x32":0,"0x33":248}}},{"setup":{"iram":{"0x30":239,"0x31":3,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":239,"0x31":3,"0x32":31,"0x33":255}}},{"setup":{"iram":{"0x30":237,"0x31":2,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":237,"0x31":2,"0x32":21,"0x33":253}}},{"setup":{"iram":{"0x30":232,"0x31":3,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":232,"0x31":3,"0x32":24,"0x33":248}}},{"setup":{"iram":{"0x30":239,"0x31":0,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":239,"0x31":0,"0x32":7,"0x33":255}}}]},"hints":["Số thanh ghi n là 3 bit thấp của mã lệnh: ANL A,#07H giữ lại 3 bit đó.","Địa chỉ = 8 × băng + n. Nhân 8 bằng ba lần RL A (băng ≤ 3 nên không tràn), rồi cộng n.","Mã của MOV Rn,A cũng có n ở 3 bit thấp, phần còn lại là hằng: một phép OR là ghép được. Giữ n ở chỗ khác vì cần dùng hai lần."],"why":"Mã lệnh của họ MOV A,Rn là 1110 1rrr: 5 bit cao chọn phép toán, 3 bit thấp rrr chọn thanh ghi. Bộ giải mã của CPU ghép rrr với RS1 RS0 trong PSW thành địa chỉ RAM: 8 × băng + n. Cùng rrr dùng cho MOV Rn,A (1111 1rrr)."},{"t":"Tính độ dời SJMP trong 7 chu kỳ","d":"<p>Ô <code>30H<\/code> chứa byte thấp địa chỉ của một lệnh <code>SJMP<\/code>, ô <code>31H<\/code> chứa byte thấp địa chỉ đích (đề bảo đảm đích nằm trong tầm −128…+127). Ghi độ dời mà trình dịch đặt vào byte thứ hai của lệnh <code>SJMP<\/code> vào <code>32H<\/code>. Code mẫu cho kết quả sai và chậm. Sửa để đúng với mọi bộ thử, chạy không quá <b>7 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và mã dài không quá <b>11 byte<\/b>.<\/p><p>Ví dụ: <code>30H = 06H<\/code>, <code>31H = 0AH<\/code> → <code>32H = 02H<\/code> (lệnh <code>SJMP TIEP<\/code> của Bài 6).<\/p>","start":"        ORG     0000H\n; Sai kết quả và chậm: sửa cho đúng, <= 7 chu kỳ\n        MOV     A,31H                   ; đích\n        CLR     C\n        SUBB    A,30H                   ; đích - địa chỉ SJMP\n        MOV     R7,A\n        MOV     A,R7\n        MOV     32H,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":6,"0x31":10,"0x32":238}},"expect":{"iram":{"0x30":6,"0x31":10,"0x32":2}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":254}}},{"setup":{"iram":{"0x30":16,"0x31":3,"0x32":238}},"expect":{"iram":{"0x30":16,"0x31":3,"0x32":241}}},{"setup":{"iram":{"0x30":32,"0x31":161,"0x32":238}},"expect":{"iram":{"0x30":32,"0x31":161,"0x32":127}}},{"setup":{"iram":{"0x30":144,"0x31":18,"0x32":238}},"expect":{"iram":{"0x30":144,"0x31":18,"0x32":128}}},{"setup":{"iram":{"0x30":253,"0x31":255,"0x32":238}},"expect":{"iram":{"0x30":253,"0x31":255,"0x32":0}}},{"setup":{"iram":{"0x30":240,"0x31":5,"0x32":238}},"expect":{"iram":{"0x30":240,"0x31":5,"0x32":19}}}],"maxCyc":7,"maxBytes":11},"hints":["Độ dời tính từ PC của lệnh kế tiếp, tức địa chỉ SJMP + 2. Thử bộ thử 30H = 00H, 31H = 00H: SJMP $ có độ dời bao nhiêu?","Độ dời = đích − (địa chỉ + 2), lấy 8 bit. Code mẫu quên phần + 2 và có hai lệnh thừa (MOV R7,A rồi MOV A,R7).","Không cần SUBB: thử viết đích − (x + 2) bằng một phép đảo bit, một phép cộng và một lệnh tăng/giảm 1."],"why":"SJMP rel: PC mới = (địa chỉ SJMP + 2) + rel, nên rel = đích − địa chỉ − 2 (lấy 8 bit). Với SJMP $: rel = −2 = FEH. Cách nhanh: CPL A biến địa chỉ thành −địa chỉ − 1, cộng đích rồi DEC A: 5 lệnh 1 chu kỳ + SJMP $ = 7 chu kỳ, 10 byte."}]);

makeQuiz("quiz7","score7",[{"q": "Dãy byte 75 30 45 trong bộ nhớ chương trình là lệnh nào?", "o": ["MOV 30H,#45H", "MOV 45H,#30H", "MOV 30H,45H", "MOV A,#45H rồi một byte dữ liệu"], "a": 0, "e": "75H là MOV direct,#data: byte 2 là địa chỉ đích (30H), byte 3 là dữ liệu (45H). Đọc ngược thứ tự là lỗi hay gặp; MOV 30H,45H có mã 85H, không phải 75H."}, {"q": "Dãy byte 85 30 31 là lệnh nào?", "o": ["MOV 30H,31H (chép ô 31H sang ô 30H)", "MOV 30H,#31H", "MOV 31H,30H (chép ô 30H sang ô 31H)", "MOV 31H,#30H"], "a": 2, "e": "Với MOV direct,direct (85H), byte 2 là địa chỉ nguồn, byte 3 là địa chỉ đích, ngược với thứ tự viết trong hợp ngữ. Hai lựa chọn có # là mã 75H."}, {"q": "Dãy byte 74 05 F8 08 E8 bắt đầu ở 0000H gồm bao nhiêu lệnh?", "o": ["4 lệnh: MOV A,#05H; MOV R0,A; INC R0; MOV A,R0", "5 lệnh, mỗi byte một lệnh", "3 lệnh: MOV A,#05H; MOV R0,#08H; MOV A,R0", "2 lệnh: MOV A,#05H; MOV 08H,R0"], "a": 0, "e": "74H dài 2 byte (74 05), F8H = MOV R0,A dài 1 byte, 08H = INC R0, E8H = MOV A,R0. Coi 08 là dữ liệu của F8 là nhầm: F8 không có toán hạng."}, {"q": "Lệnh MOV A,#5AH nằm ở 0040H. Khi CPU đang thực thi lệnh này (đã nạp đủ hai byte), PC bằng bao nhiêu?", "o": ["0040H", "0041H", "005AH", "0042H"], "a": 3, "e": "Mỗi byte nạp làm PC tăng 1; sau khi nạp hai byte, PC = 0042H, địa chỉ lệnh kế tiếp. 0041H là PC sau khi mới nạp mã lệnh, chưa nạp toán hạng."}, {"q": "Một bảng DB 04H,04H đặt ngay sau MOV A,#10H, không có lệnh nhảy qua. Chuyện gì xảy ra?", "o": ["CPU tự bỏ qua vùng DB", "CPU chạy hai byte đó như hai lệnh INC A", "CPU dừng lại khi gặp DB", "Trình dịch báo lỗi vì DB nằm giữa lệnh"], "a": 1, "e": "DB chỉ là chỉ thị cho trình dịch đặt byte vào bộ nhớ; CPU không biết byte đó là dữ liệu. 04H là mã của INC A nên A tăng hai lần. Trình dịch không kiểm vị trí bảng."}]);

